'use client';

import type { User } from '@openfort/openfort-js';
import { RecoveryMethod, useSignOut, useUI, useUser } from '@openfort/react';
import { useEthereumEmbeddedWallet } from '@openfort/react/ethereum';
import {
  checkOpenfortUser,
  exchangeOpenfortSession,
  getBackendMe,
  logoutBackendSession,
  refreshBackendSession,
  type BackendMeResponse,
} from '@/lib/backend-auth-client';
import {
  QualificationQuestionnaire,
  type QualificationSubmission,
} from './qualification-questionnaire';
import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from 'react';

type AppSessionStatus =
  | 'idle'
  | 'loading'
  | 'needs_onboarding'
  | 'creating_wallet'
  | 'authenticated'
  | 'unauthenticated'
  | 'error';

interface AuthSessionContextValue {
  status: AppSessionStatus;
  backendAccessToken: string | null;
  backendUser: BackendMeResponse | null;
  openfortUser: User | null;
  isOpenfortLoading: boolean;
  isOpenfortAuthenticated: boolean;
  error: string | null;
  retry: () => void;
}

const AuthSessionContext = createContext<AuthSessionContextValue | null>(null);
const ONBOARDING_STORAGE_KEY = 'infrafund:onboarding-draft';

function getErrorMessage(error: unknown) {
  if (error instanceof Error && error.message) {
    return error.message;
  }

  return 'Failed to initialize your session.';
}

function clearOnboardingDraft() {
  if (typeof window !== 'undefined') {
    window.sessionStorage.removeItem(ONBOARDING_STORAGE_KEY);
  }
}

function normalizeRole(role: QualificationSubmission['role']) {
  if (role === 'client') {
    return 'project_owner';
  }

  if (role === 'dao') {
    return 'governance';
  }

  return role;
}

export function AuthSessionProvider({ children }: { children: ReactNode }) {
  const { user, isLoading, isAuthenticated, getAccessToken } = useUser();
  const { signOut } = useSignOut();
  const { close: closeOpenfortModal } = useUI();
  const { create, wallets } = useEthereumEmbeddedWallet();
  const openfortUserId = user?.id ?? null;
  const [status, setStatus] = useState<AppSessionStatus>('idle');
  const [backendAccessToken, setBackendAccessToken] = useState<string | null>(
    null
  );
  const [backendUser, setBackendUser] = useState<BackendMeResponse | null>(
    null
  );
  const [error, setError] = useState<string | null>(null);
  const [retryCount, setRetryCount] = useState(0);
  const [pendingOnboardingAccessToken, setPendingOnboardingAccessToken] =
    useState<string | null>(null);
  const [pendingWalletCreation, setPendingWalletCreation] = useState<{
    accessToken: string;
    user: BackendMeResponse;
  } | null>(null);
  const previousAuthState = useRef(false);
  const bootstrapAttemptKeyRef = useRef<string | null>(null);

  const clearSession = useCallback(() => {
    setBackendAccessToken(null);
    setBackendUser(null);
    setPendingOnboardingAccessToken(null);
    setPendingWalletCreation(null);
    setError(null);
    bootstrapAttemptKeyRef.current = null;
    clearOnboardingDraft();
  }, []);

  const finalizeAuthenticatedSession = useCallback(
    (accessToken: string, currentUser: BackendMeResponse) => {
      closeOpenfortModal();
      setBackendAccessToken(accessToken);
      setBackendUser(currentUser);
      setPendingOnboardingAccessToken(null);
      setPendingWalletCreation(null);
      setError(null);
      clearOnboardingDraft();
      setStatus('authenticated');
    },
    [closeOpenfortModal]
  );

  const createWalletIfNeeded = useCallback(
    async (accessToken: string, currentUser: BackendMeResponse) => {
      setBackendAccessToken(accessToken);
      setBackendUser(currentUser);
      setPendingWalletCreation({ accessToken, user: currentUser });

      if (wallets.length > 0) {
        finalizeAuthenticatedSession(accessToken, currentUser);
        return;
      }

      setStatus('creating_wallet');

      try {
        await create({
          recoveryMethod: RecoveryMethod.AUTOMATIC,
        });
        finalizeAuthenticatedSession(accessToken, currentUser);
      } catch (walletError) {
        setError(getErrorMessage(walletError));
        setStatus('error');
      }
    },
    [create, finalizeAuthenticatedSession, wallets.length]
  );

  const bootstrapSession = useCallback(async () => {
    if (!openfortUserId) {
      clearSession();
      setStatus('unauthenticated');
      return;
    }

    setStatus('loading');
    setError(null);

    try {
      const refreshedSession = await refreshBackendSession().catch(() => null);

      if (refreshedSession) {
        const me = await getBackendMe(refreshedSession.access_token);
        finalizeAuthenticatedSession(refreshedSession.access_token, me);
        return;
      }

      const openfortAccessToken = await getAccessToken();

      if (!openfortAccessToken) {
        throw new Error('Openfort access token is unavailable.');
      }

      const checkResponse = await checkOpenfortUser(openfortAccessToken);

      if (!checkResponse.exists) {
        closeOpenfortModal();
        setPendingOnboardingAccessToken(openfortAccessToken);
        setStatus('needs_onboarding');
        return;
      }

      const loginResponse = await exchangeOpenfortSession(openfortAccessToken);
      const me = await getBackendMe(loginResponse.access_token);

      finalizeAuthenticatedSession(loginResponse.access_token, me);
    } catch (sessionError) {
      clearSession();
      setError(getErrorMessage(sessionError));
      setStatus('error');
    }
  }, [
    clearSession,
    closeOpenfortModal,
    finalizeAuthenticatedSession,
    getAccessToken,
    openfortUserId,
  ]);

  const completeOnboarding = useCallback(
    async ({ role, type, organizationName }: QualificationSubmission) => {
      if (!pendingOnboardingAccessToken) {
        setError('Openfort access token is unavailable.');
        setStatus('error');
        return;
      }

      setStatus('loading');
      setError(null);

      try {
        const loginResponse = await exchangeOpenfortSession(
          pendingOnboardingAccessToken,
          {
            role: normalizeRole(role),
            type,
            organization_name:
              type === 'organization' ? organizationName?.trim() : undefined,
          }
        );
        const me = await getBackendMe(loginResponse.access_token);

        await createWalletIfNeeded(loginResponse.access_token, me);
      } catch (sessionError) {
        setError(getErrorMessage(sessionError));
        setStatus('needs_onboarding');
      }
    },
    [createWalletIfNeeded, pendingOnboardingAccessToken]
  );

  const abandonOnboarding = useCallback(async () => {
    clearSession();
    setStatus('loading');

    await Promise.allSettled([
      logoutBackendSession(),
      signOut().catch(() => undefined),
    ]);

    clearSession();
    setStatus('unauthenticated');
  }, [clearSession, signOut]);

  const retry = useCallback(() => {
    if (pendingWalletCreation) {
      void createWalletIfNeeded(
        pendingWalletCreation.accessToken,
        pendingWalletCreation.user
      );
      return;
    }

    setRetryCount((count) => count + 1);
  }, [createWalletIfNeeded, pendingWalletCreation]);

  useEffect(() => {
    if (isLoading) {
      setStatus((currentStatus) =>
        currentStatus === 'authenticated' ||
        currentStatus === 'needs_onboarding'
          ? currentStatus
          : 'loading'
      );
      return;
    }

    if (!isAuthenticated || !openfortUserId) {
      clearSession();
      setStatus('unauthenticated');
      return;
    }

    const bootstrapAttemptKey = `${openfortUserId}:${retryCount}`;

    if (bootstrapAttemptKeyRef.current === bootstrapAttemptKey) {
      return;
    }

    bootstrapAttemptKeyRef.current = bootstrapAttemptKey;

    void bootstrapSession();
  }, [
    bootstrapSession,
    clearSession,
    isAuthenticated,
    isLoading,
    openfortUserId,
    retryCount,
  ]);

  useEffect(() => {
    const signedOut =
      previousAuthState.current && !isLoading && !isAuthenticated;

    previousAuthState.current = isAuthenticated;

    if (!signedOut) {
      return;
    }

    clearSession();
    setStatus('unauthenticated');
    void logoutBackendSession().catch(() => undefined);
  }, [clearSession, isAuthenticated, isLoading]);

  const value = useMemo<AuthSessionContextValue>(
    () => ({
      status,
      backendAccessToken,
      backendUser,
      openfortUser: user,
      isOpenfortLoading: isLoading,
      isOpenfortAuthenticated: isAuthenticated,
      error,
      retry,
    }),
    [
      status,
      backendAccessToken,
      backendUser,
      user,
      isLoading,
      isAuthenticated,
      error,
      retry,
    ]
  );

  return (
    <AuthSessionContext.Provider value={value}>
      {children}
      <QualificationQuestionnaire
        isOpen={status === 'needs_onboarding'}
        openfortUser={user}
        submitError={error}
        isSubmitting={status === 'loading'}
        onClose={() => {
          void abandonOnboarding();
        }}
        onSubmit={completeOnboarding}
        onDisqualifiedSuccess={abandonOnboarding}
      />
    </AuthSessionContext.Provider>
  );
}

export function useAuthSession() {
  const context = useContext(AuthSessionContext);

  if (!context) {
    throw new Error(
      'useAuthSession must be used within an AuthSessionProvider.'
    );
  }

  return context;
}

'use client';

interface BackendLoginResponse {
  user_id: string;
  access_token: string;
  expires_at: string;
}

interface BackendCheckResponse {
  exists: boolean;
}

interface BackendCountriesResponse {
  items: BackendCountryRecord[];
}

interface BackendCountryRecord {
  ID?: number;
  id?: number;
  Name?: string;
  name?: string;
  Iso?: string;
  iso?: string;
  Iso3?: string;
  iso3?: string;
  Code?: number;
  code?: number;
  PhoneCode?: number;
  phone_code?: number;
}

export interface CountryOption {
  id: number;
  name: string;
  iso?: string;
  iso3?: string;
  code?: number;
  phoneCode?: number;
}

interface OpenfortExchangePayload {
  first_name?: string;
  last_name?: string;
  organization_name?: string;
  phone_number?: string;
  email?: string;
  type?: 'individual' | 'organization';
  role?: string;
}

interface NonResidentIndividualPayload {
  first_name: string;
  last_name: string;
  email: string;
  country_id: number;
}

interface NonResidentCompanyPayload {
  first_name: string;
  last_name: string;
  company_name: string;
  email: string;
  country_id: number;
}

export interface BackendMeResponse {
  user_id: string;
  openfort_user_id: string;
  email: string | null;
  first_name: string | null;
  last_name: string | null;
  company_name: string | null;
  phone_number: string | null;
  type: string;
  role: string;
  status: string;
  kyc_verified: boolean;
  kyb_verified: boolean;
}

interface SuccessResponse<T> {
  code: string;
  data: T;
}

interface ErrorResponse {
  message?: string;
  detail?: string;
}

function getApiBaseUrl() {
  return (
    process.env.NEXT_PUBLIC_API_BASE_URL ??
    process.env.NEXT_PUBLIC_BASE_URL ??
    ''
  ).replace(/\/+$/, '');
}

function buildUrl(path: string) {
  const normalizedPath = path.replace(/^\/+/, '');
  const baseUrl = getApiBaseUrl();

  return baseUrl ? `${baseUrl}/${normalizedPath}` : `/v1/${normalizedPath}`;
}

async function request<T>(
  path: string,
  init: RequestInit & { accessToken?: string } = {}
) {
  const headers = new Headers(init.headers);

  if (init.body && !headers.has('Content-Type')) {
    headers.set('Content-Type', 'application/json');
  }

  if (init.accessToken) {
    headers.set('Authorization', `Bearer ${init.accessToken}`);
  }

  const response = await fetch(buildUrl(path), {
    ...init,
    headers,
    credentials: 'include',
  });

  if (!response.ok) {
    let message = 'Request failed';

    try {
      const errorBody = (await response.json()) as ErrorResponse;
      message = errorBody.message || errorBody.detail || message;
    } catch {}

    throw new Error(message);
  }

  if (response.status === 204) {
    return null as T;
  }

  const body = (await response.json()) as SuccessResponse<T>;
  return body.data;
}

function normalizeCountry(country: BackendCountryRecord): CountryOption {
  return {
    id: Number(country.ID ?? country.id ?? 0),
    name: String(country.Name ?? country.name ?? ''),
    iso:
      typeof country.Iso === 'string'
        ? country.Iso
        : typeof country.iso === 'string'
          ? country.iso
          : undefined,
    iso3:
      typeof country.Iso3 === 'string'
        ? country.Iso3
        : typeof country.iso3 === 'string'
          ? country.iso3
          : undefined,
    code:
      typeof country.Code === 'number'
        ? country.Code
        : typeof country.code === 'number'
          ? country.code
          : undefined,
    phoneCode:
      typeof country.PhoneCode === 'number'
        ? country.PhoneCode
        : typeof country.phone_code === 'number'
          ? country.phone_code
          : undefined,
  };
}

export async function checkOpenfortUser(openfortAccessToken: string) {
  return request<BackendCheckResponse>('auth/openfort/check', {
    method: 'GET',
    accessToken: openfortAccessToken,
  });
}

export async function exchangeOpenfortSession(
  openfortAccessToken: string,
  body: OpenfortExchangePayload = {}
) {
  return request<BackendLoginResponse>('auth/openfort/exchange', {
    method: 'POST',
    accessToken: openfortAccessToken,
    body: JSON.stringify(body),
  });
}

export async function refreshBackendSession() {
  return request<BackendLoginResponse>('auth/refresh', {
    method: 'POST',
  });
}

export async function getBackendMe(accessToken: string) {
  return request<BackendMeResponse>('me', {
    method: 'GET',
    accessToken,
  });
}

export async function getCountries() {
  const response = await request<BackendCountriesResponse>(
    'locations/countries',
    {
      method: 'GET',
    }
  );

  return response.items
    .map(normalizeCountry)
    .filter((country) => country.id > 0 && country.name);
}

export async function submitNonResidentIndividual(
  payload: NonResidentIndividualPayload,
  captchaToken: string
) {
  await request<null>('non-resident-waitlist/individual', {
    method: 'POST',
    headers: {
      'X-Captcha-Token': captchaToken,
    },
    body: JSON.stringify(payload),
  });
}

export async function submitNonResidentCompany(
  payload: NonResidentCompanyPayload,
  captchaToken: string
) {
  await request<null>('non-resident-waitlist/company', {
    method: 'POST',
    headers: {
      'X-Captcha-Token': captchaToken,
    },
    body: JSON.stringify(payload),
  });
}

export async function logoutBackendSession() {
  await request<null>('auth/logout', {
    method: 'POST',
  });
